WITH base AS (SELECT *, ADD_MONTHS(last_restock, 12) AS last_restock_plus_months FROM inventory WHERE quantity <= 110), inventory_stats AS (SELECT product_id, YEAR(last_restock) AS last_restock_year, COUNT(quantity) AS quantity_count, MIN(quantity) AS min_quantity FROM base GROUP BY product_id, YEAR(last_restock)) SELECT * FROM inventory_stats ORDER BY min_quantity, quantity_count, product_id, last_restock_year LIMIT 10
